UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Save Game")
TSubclassOf<USaveGame> SaveGameClass;

void SaveGame()
{
    USaveGame* SaveGameInstance = Cast<USaveGame>(UGameplayStatics::CreateSaveGameObject(SaveGameClass));
    if (SaveGameInstance)
    {
        SaveGameInstance->CurrentLevel = CurrentLevel;
        SaveGameInstance->PlayerStats = PlayerStats;
        SaveGameInstance->Inventory = Inventory;
        UGameplayStatics::SaveGameToSlot(SaveGameInstance, SaveGameInstance->SlotName, SaveGameInstance->UserIndex);
    }
}

void LoadGame()
{
    USaveGame* SaveGameInstance = Cast<USaveGame>(UGameplayStatics::LoadGameFromSlot(SaveGameInstance->SlotName, SaveGameInstance->UserIndex));
    if (SaveGameInstance)
    {
        CurrentLevel = SaveGameInstance->CurrentLevel;
        PlayerStats = SaveGameInstance->PlayerStats;
        Inventory = SaveGameInstance->Inventory;
    }
}
```
